const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Windhoek, Namibia geometry
  const windhoek = ee.Geometry.Point([17.0832, -22.5597]); // Windhoek coordinates
  const bufferDist = 25000; // 25 km buffer for area analysis
  const aoiGeom = windhoek.buffer(bufferDist);

  // 2. Cloud masking functions
  function maskCloudsS2(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    return image.updateMask(qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0)));
  }

  function maskCloudsL8(image) {
    const qa = image.select('BQA');
    return image.updateMask(qa.lt(2800)); // Mask clouds and shadows
  }

  function calcNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  function calcNDVIL8(image) {
    return image.normalizedDifference(['B5', 'B4']).rename('NDVI');
  }

  // 3. Fetch February 2021 data (Sentinel-2)
  const feb2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoiGeom)
    .filterDate('2021-02-01', '2021-02-28')
    .map(maskCloudsS2)
    .map(calcNDVI);

  const feb2021Size = feb2021.size().getInfo();
  console.log(`Feb 2021 (S2) Images: ${feb2021Size}`);

  if (feb2021Size === 0) {
    // Fallback to Landsat 8
    const feb2021L8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(aoiGeom)
      .filterDate('2021-02-01', '2021-02-28')
      .map(maskCloudsL8)
      .map(calcNDVIL8);

    const feb2021L8Size = feb2021L8.size().getInfo();
    console.log(`Feb 2021 (L8) Images: ${feb2021L8Size}`);

    if (feb2021L8Size === 0) {
      console.log('No images found for Feb 2021.');
      console.log('C1');
      return;
    }
  }

  // 4. Aggregate Feb 2021 NDVI (use mean composite)
  const feb2021Composite = feb2021.mean();
  const feb2021ValidPixels = feb2021Composite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoiGeom,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Feb 2021 Valid Pixels: ${feb2021ValidPixels}`);

  if (feb2021ValidPixels === 0) {
    console.log('No valid pixels for Feb 2021 after masking.');
    console.log('C2');
    return;
  }

  const feb2021NDVI = feb2021Composite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoiGeom,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Feb 2021 Mean NDVI: ${feb2021NDVI?.toFixed(4) || 'NULL'}`);

  // 5. Fetch Feb 2010-2020 historical data
  // Use Landsat for 2010-2012 (Landsat 5/7), Landsat 8 for 2013+
  let febHistorical = ee.ImageCollection([]);

  // Landsat 5 & 7 for 2010-2012
  const febL5L7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(aoiGeom)
    .filterDate('2010-02-01', '2013-02-28')
    .map(maskCloudsL8)
    .map(calcNDVIL8);

  // Landsat 8 for 2013-2020
  const febL8Hist = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(aoiGeom)
    .filterDate('2013-02-01', '2020-02-28')
    .map(maskCloudsL8)
    .map(calcNDVIL8);

  // Sentinel-2 for 2015-2020
  const febS2Hist = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoiGeom)
    .filterDate('2015-02-01', '2020-02-28')
    .map(maskCloudsS2)
    .map(calcNDVI);

  febHistorical = febL5L7.merge(febL8Hist).merge(febS2Hist);

  const febHistSize = febHistorical.size().getInfo();
  console.log(`Feb 2010-2020 Historical Images: ${febHistSize}`);

  if (febHistSize === 0) {
    console.log('No historical Feb data found for 2010-2020.');
    console.log('C1');
    return;
  }

  // 6. Calculate Feb 2010-2020 mean NDVI
  const febHistComposite = febHistorical.mean();
  const febHistValidPixels = febHistComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoiGeom,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Feb 2010-2020 Valid Pixels: ${febHistValidPixels}`);

  if (febHistValidPixels === 0) {
    console.log('No valid pixels for historical Feb data.');
    console.log('C2');
    return;
  }

  const febHistNDVI = febHistComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoiGeom,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Feb 2010-2020 Mean NDVI: ${febHistNDVI?.toFixed(4) || 'NULL'}`);

  // 7. Validation & Final Answer
  if (feb2021NDVI === null || febHistNDVI === null || 
      isNaN(feb2021NDVI) || isNaN(febHistNDVI) ||
      feb2021NDVI < -1 || feb2021NDVI > 1 ||
      febHistNDVI < -1 || febHistNDVI > 1) {
    console.log('Invalid NDVI calculation result.');
    console.log('C3');
    return;
  }

  console.log(`Feb 2021 NDVI: ${feb2021NDVI.toFixed(4)}, Feb 2010-2020 Avg: ${febHistNDVI.toFixed(4)}`);

  if (feb2021NDVI > febHistNDVI) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
